macro_rules! deps {
    () => {
        DFA!();
        Match!();
        NFA!();
        Config!();
    };
}

macro_rules! BoundedBacktracker {
    () => {
        deps!();
        # [doc = " A backtracking regex engine that bounds its execution to avoid exponential"] # [doc = " blow-up."] # [doc = ""] # [doc = " This regex engine only implements leftmost-first match semantics and"] # [doc = " only supports leftmost searches. It effectively does the same thing as a"] # [doc = " [`PikeVM`](thompson::pikevm::PikeVM), but typically does it faster because"] # [doc = " it doesn't have to worry about copying capturing group spans for most NFA"] # [doc = " states. Instead, the backtracker can maintain one set of captures (provided"] # [doc = " by the caller) and never needs to copy them. In exchange, the backtracker"] # [doc = " bounds itself to ensure it doesn't exhibit worst case exponential time."] # [doc = " This results in the backtracker only being able to handle short haystacks"] # [doc = " given reasonable memory usage."] # [doc = ""] # [doc = " # Searches may return an error!"] # [doc = ""] # [doc = " By design, this backtracking regex engine is bounded. This bound is"] # [doc = " implemented by not visiting any combination of NFA state ID and position"] # [doc = " in a haystack more than once. Thus, the total memory required to bound"] # [doc = " backtracking is proportional to `haystack.len() * nfa.states().len()`."] # [doc = " This can obviously get quite large, since large haystacks aren't terribly"] # [doc = " uncommon. To avoid using exorbitant memory, the capacity is bounded by"] # [doc = " a fixed limit set via [`Config::visited_capacity`]. Thus, if the total"] # [doc = " capacity required for a particular regex and a haystack exceeds this"] # [doc = " capacity, then the search routine will return an error."] # [doc = ""] # [doc = " Unlike other regex engines that may return an error at search time (like"] # [doc = " the DFA or the hybrid NFA/DFA), there is no way to guarantee that a bounded"] # [doc = " backtracker will work for every haystack. Therefore, this regex engine"] # [doc = " _only_ exposes fallible search routines to avoid the footgun of panicking"] # [doc = " when running a search on a haystack that is too big."] # [doc = ""] # [doc = " If one wants to use the fallible search APIs without handling the"] # [doc = " error, the only way to guarantee an error won't occur from the"] # [doc = " haystack length is to ensure the haystack length does not exceed"] # [doc = " [`BoundedBacktracker::max_haystack_len`]."] # [doc = ""] # [doc = " # Example: Unicode word boundaries"] # [doc = ""] # [doc = " This example shows that the bounded backtracker implements Unicode word"] # [doc = " boundaries correctly by default."] # [doc = ""] # [doc = " ```"] # [doc = " # if cfg!(miri) { return Ok(()); } // miri takes too long"] # [doc = " use regex_automata::{nfa::thompson::backtrack::BoundedBacktracker, Match};"] # [doc = ""] # [doc = " let re = BoundedBacktracker::new(r\"\\b\\w+\\b\")?;"] # [doc = " let mut cache = re.create_cache();"] # [doc = ""] # [doc = " let mut it = re.try_find_iter(&mut cache, \"Шерлок Холмс\");"] # [doc = " assert_eq!(Some(Ok(Match::must(0, 0..12))), it.next());"] # [doc = " assert_eq!(Some(Ok(Match::must(0, 13..23))), it.next());"] # [doc = " assert_eq!(None, it.next());"] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [doc = ""] # [doc = " # Example: multiple regex patterns"] # [doc = ""] # [doc = " The bounded backtracker supports searching for multiple patterns"] # [doc = " simultaneously, just like other regex engines. Note though that because it"] # [doc = " uses a backtracking strategy, this regex engine is unlikely to scale well"] # [doc = " as more patterns are added. But then again, as more patterns are added, the"] # [doc = " maximum haystack length allowed will also shorten (assuming the visited"] # [doc = " capacity remains invariant)."] # [doc = ""] # [doc = " ```"] # [doc = " use regex_automata::{nfa::thompson::backtrack::BoundedBacktracker, Match};"] # [doc = ""] # [doc = " let re = BoundedBacktracker::new_many(&[\"[a-z]+\", \"[0-9]+\"])?;"] # [doc = " let mut cache = re.create_cache();"] # [doc = ""] # [doc = " let mut it = re.try_find_iter(&mut cache, \"abc 1 foo 4567 0 quux\");"] # [doc = " assert_eq!(Some(Ok(Match::must(0, 0..3))), it.next());"] # [doc = " assert_eq!(Some(Ok(Match::must(1, 4..5))), it.next());"] # [doc = " assert_eq!(Some(Ok(Match::must(0, 6..9))), it.next());"] # [doc = " assert_eq!(Some(Ok(Match::must(1, 10..14))), it.next());"] # [doc = " assert_eq!(Some(Ok(Match::must(1, 15..16))), it.next());"] # [doc = " assert_eq!(Some(Ok(Match::must(0, 17..21))), it.next());"] # [doc = " assert_eq!(None, it.next());"] # [doc = " # Ok::<(), Box<dyn std::error::Error>>(())"] # [doc = " ```"] # [derive (Clone , Debug)] pub struct BoundedBacktracker { config : Config , nfa : NFA , }
    };
}

BoundedBacktracker!();